"""Starter configurations, one per geometry type: the files `geometry <type> init` writes.

Each template below is exactly the file `geometry <type> init` writes. The
[points] and [output] tables repeat on purpose: every template reads as a
complete, standalone file.
"""

# --------------------------------------------------
# starter configurations
# --------------------------------------------------
PLATE_TEMPLATE = """\
# Generated by: geometry plate init
# Edit this file, then run: geometry plate run plate.toml

# Flat plate with a circular leading edge (upper half).
# Stagnation point at the origin, x downstream, y up.
[geometry]
# type marker
type = "plate"
# nose radius in [m]
nose_radius = 100.0e-6
# length of flat plate, measured from nose tip in [m]
length = 0.5

# Points per piece, each count including both ends of the piece. The junction
# is always a sample point; nose points are equally spaced in angle.
[points]
# number of points on the nose arc (91 = 1 deg steps on the 90 deg arc)
n_nose = 91
# number of points on the flat part of the plate
n_body = 200

# The path is relative to this file.
[output]
# moldline file: .csv, or .dat for Tecplot ASCII
# columns: x, y, z, s in [m]; nx, ny, nz; curvature in [1/m]
file = "plate.csv"
"""

WEDGE_TEMPLATE = """\
# Generated by: geometry wedge init
# Edit this file, then run: geometry wedge run wedge.toml

# Paths are rela
# Planar blunted wedge (upper half). The nose arc runs to 90 deg - half_angle,
# tangent to the body. Stagnation point at the origin, x downstream, y up.
[geometry]
# type marker
type = "wedge"
# nose radius in [m]
nose_radius = 100.0e-6
# length of wedge, measured axially from nose tip in [m]
length = 0.5
# half-angle of the body in [deg]
half_angle = 7.0

# Points per piece, each count including both ends of the piece. The junction
# is always a sample point; nose points are equally spaced in angle.
[points]
# number of points on the nose arc (84 = 1 deg steps on the 83 deg arc)
n_nose = 84
# number of points on the body
n_body = 200

# The path is relative to this file.
[output]
# moldline file: .csv, or .dat for Tecplot ASCII
# columns: x, y, z, s in [m]; nx, ny, nz; curvature in [1/m]
file = "wedge.csv"
"""

CONE_TEMPLATE = """\
# Generated by: geometry cone init
# Edit this file, then run: geometry cone run cone.toml

# Sphere-cone, axisymmetric about the x axis; the moldline is its meridian.
# The nose arc runs to 90 deg - half_angle, tangent to the cone.
# Stagnation point at the origin, x along the axis, y radial.
[geometry]
# type marker
type = "cone"
# nose radius in [m]
nose_radius = 100.0e-6
# length of cone, measured axially from nose tip in [m]
length = 0.5
# cone half-angle in [deg]
half_angle = 7.0

# Points per piece, each count including both ends of the piece. The junction
# is always a sample point; nose points are equally spaced in angle.
[points]
# number of points on the nose arc (84 = 1 deg steps on the 83 deg arc)
n_nose = 84
# number of points on the cone surface
n_body = 200

# The path is relative to this file.
[output]
# moldline file: .csv, or .dat for Tecplot ASCII
# columns: x, y, z, s in [m]; nx, ny, nz; curvature in [1/m]
file = "cone.csv"
"""

TANGENT_OGIVE_TEMPLATE = """\
# Generated by: geometry tangent-ogive init
# Edit this file, then run: geometry tangent-ogive run tangent-ogive.toml

# Spherically blunted tangent ogive, axisymmetric about the x axis; the moldline is
# its meridian. The ogive is a circular arc tangent to the base cylinder; the nose
# sphere sits on the axis, tangent to that arc. Optionally a cylinder follows the base.
# Stagnation point at the origin, x along the axis, y radial.
[geometry]
# type marker
type = "tangent-ogive"
# nose radius in [m] (smaller than base_radius)
nose_radius = 100.0e-6
# length of the sharp ogive, tip to base, in [m]; blunting makes the body slightly
# shorter (the sharp tip would lie upstream of the stagnation point)
length = 0.5
# base radius in [m] (smaller than length)
base_radius = 0.05
# length of the cylinder after the base in [m]; 0 for none (then no n_cylinder)
cylinder_length = 0.0

# Points per piece, each count including both ends of the piece. The junctions
# are always sample points; nose points are equally spaced in angle.
[points]
# number of points on the nose arc (80 = about 1 deg steps on the 78.6 deg arc)
n_nose = 80
# number of points on the ogive
n_body = 200
# number of points on the cylinder (needed when cylinder_length > 0)
# n_cylinder = 50

# The path is relative to this file.
[output]
# moldline file: .csv, or .dat for Tecplot ASCII
# columns: x, y, z, s in [m]; nx, ny, nz; curvature in [1/m]
file = "tangent-ogive.csv"
"""


# --------------------------------------------------
# registry: one starter configuration per geometry type
# --------------------------------------------------
# keys are the [geometry] type values (and the CLI command names)
GEOMETRY_TEMPLATES: dict[str, str] = {
    "plate": PLATE_TEMPLATE,
    "wedge": WEDGE_TEMPLATE,
    "cone": CONE_TEMPLATE,
    "tangent-ogive": TANGENT_OGIVE_TEMPLATE,
}
